Projection.rate_scenario_path:
def rate_scenario_path():
    """The model point's index and MVA reference-yield path, by policy year."""
    return data.rate_scenario().loc[scenario_id()]

Projection.scenario_value:
def scenario_value(y, field):
    """Step-function lookup of column ``name`` in the model point's scenario at anniversary ``y``.

    **The argument is an anniversary number, not the frame's month index.** The ``t``
    column of *rate_scenario.csv* is an anniversary number, ``0`` at issue, and the file's
    keys are read unshifted; callers pass ``duration(t)`` for the anniversary opening the
    contract year of month ``t`` and ``duration(t) + 1`` for the one closing it.  Each row
    states the level that holds from its own anniversary until the next row of the same
    scenario, so a flat path is one row.  Anniversaries before the first row take the
    first row's level.
    """
    sub = rate_scenario_path()
    key = sub.index.asof(y) if y >= sub.index[0] else sub.index[0]
    if field == ScenarioField.index_level:
        return float(sub.loc[key, "index_level"])
    elif field == ScenarioField.mva_ref_yield:
        return float(sub.loc[key, "mva_ref_yield"])
    else:
        raise ValueError("invalid scenario field")

Projection.rollup_schedule:
def rollup_schedule():
    """The policy's benefit-base rollup schedule, by first contract year of each band."""
    return data.rollup_table().loc[rollup_id()]

Projection.has_withdrawals:
def has_withdrawals():
    """Whether the withdrawal table has rows for the model point's withdrawal programme."""
    return wd_schedule_id() in data.withdrawal_table().index

Projection.withdrawal_rows:
def withdrawal_rows():
    """The model point's scheduled withdrawals (only read when has_withdrawals())."""
    return data.withdrawal_table().loc[wd_schedule_id()]
